        ToolStripMenuItem TopMenu(string title){var item=new ToolStripMenuItem(title);menu.Items.Add(item);return item;}
        void Add(ToolStripMenuItem parent,string title,Keys shortcut,Action action){var item=new ToolStripMenuItem(title);if(shortcut!=Keys.None){if((shortcut&Keys.Modifiers)==Keys.None&&(shortcut<Keys.F1||shortcut>Keys.F24))item.ShortcutKeyDisplayString=shortcut.ToString();else item.ShortcutKeys=shortcut;}if(shortcut!=Keys.None&&((shortcut&Keys.Modifiers)!=Keys.None||(shortcut>=Keys.F1&&shortcut<=Keys.F24)))shortcuts[shortcut]=action;item.Click+=delegate{action();};parent.DropDownItems.Add(item);}
        static ToolStrip Bar(){return new ToolStrip{GripStyle=ToolStripGripStyle.Hidden,RenderMode=ToolStripRenderMode.System,Padding=new Padding(2,0,2,0),ImageScalingSize=new Size(16,16),AutoSize=true,Stretch=true};}
        ToolStripButton Button(ToolStrip bar,string title,Action action,string hint,string icon){var b=new ToolStripButton(title){ToolTipText=hint,AutoToolTip=false,AccessibleName=String.IsNullOrEmpty(title)?hint:title,Margin=new Padding(0,0,1,0),Padding=new Padding(1,0,1,0)};if(icon!=null){b.Image=Glyph(icon);b.DisplayStyle=ToolStripItemDisplayStyle.Image;}b.Click+=delegate{action();};bar.Items.Add(b);return b;}
        void ToolButton(Tool tool,string title,string hint){toolButtons[tool]=Button(editbar,title,delegate{SetTool(tool);},hint,null);}
        static Image Glyph(string name){var bmp=new Bitmap(18,18);using(var g=Graphics.FromImage(bmp)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(var p=new Pen(Color.FromArgb(58,83,102),1.5f)){if(name=="singlefit"||name=="doublefit"){g.DrawRectangle(p,2,2,14,14);if(name=="doublefit")g.DrawLine(p,9,2,9,16);g.DrawLine(p,4,9,7,9);g.DrawLine(p,11,9,14,9);g.DrawLines(p,new[]{new Point(5,7),new Point(3,9),new Point(5,11)});g.DrawLines(p,new[]{new Point(13,7),new Point(15,9),new Point(13,11)});}else if(name=="menu"){g.DrawLine(p,2,4,16,4);g.DrawLine(p,2,9,16,9);g.DrawLine(p,2,14,16,14);}else if(name=="sidebar"){g.DrawRectangle(p,2,3,14,12);g.DrawLine(p,7,3,7,15);}else if(name=="read"){g.DrawLines(p,new[]{new Point(3,7),new Point(3,3),new Point(7,3)});g.DrawLines(p,new[]{new Point(11,3),new Point(15,3),new Point(15,7)});g.DrawLines(p,new[]{new Point(3,11),new Point(3,15),new Point(7,15)});g.DrawLines(p,new[]{new Point(11,15),new Point(15,15),new Point(15,11)});}else if(name=="open"){g.DrawRectangle(p,2,5,13,10);g.DrawLines(p,new[]{new Point(2,5),new Point(2,3),new Point(8,3),new Point(10,5)});}else if(name=="save"){g.DrawRectangle(p,3,2,12,14);g.DrawRectangle(p,6,2,6,5);g.DrawRectangle(p,6,10,6,6);}else if(name=="find"){g.DrawEllipse(p,2,2,9,9);g.DrawLine(p,10,10,16,16);}else{g.DrawArc(p,4,5,10,10,name=="undo"?170:10,260);if(name=="undo")g.DrawLines(p,new[]{new Point(2,4),new Point(4,9),new Point(8,6)});else g.DrawLines(p,new[]{new Point(10,6),new Point(14,9),new Point(16,4)});}}}return bmp;}
        public void Report(string text){message.Text=text;if(findResult!=null&&findbar.Visible)findResult.Text=text.StartsWith("没有找到")||text.StartsWith("在第")?text:"";}
        public void UpdateZoom(float value){string text=(value*100).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+"%";if(zoomStatus!=null)zoomStatus.Text=text;if(zoomBox!=null){syncingZoom=true;zoomBox.Text=text;syncingZoom=false;zoomEdited=false;}}
        internal bool ApplyZoom(string input){if(Document==null||canvas==null)return false;string value=(input??"").Trim().Replace("%","").Replace("％","");double percent;if(!double.TryParse(value,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out percent)||Double.IsNaN(percent)||Double.IsInfinity(percent)||percent<1||percent>6400){UpdateZoom(canvas.Zoom);Report("请输入 1% 到 6400% 之间的缩放比例，可带小数。");return false;}canvas.Fit=0;canvas.Zoom=(float)(percent/100);zoomEdited=false;canvas.Rebuild(false);return true;}
        void ClearThumbnails(){foreach(var b in thumbs.Values)b.Dispose();thumbs.Clear();thumbOrder.Clear();}
        void DrawPage(object sender,DrawItemEventArgs e){if(e.Index<0)return;e.DrawBackground();if(Document==null||e.Index>=Document.Count)return;try{Bitmap bmp;if(!thumbs.TryGetValue(e.Index,out bmp)){var sz=Document.PageSize(e.Index);int w=84,h=Math.Max(1,(int)(w*sz.Height/sz.Width));if(h>108){h=108;w=Math.Max(1,(int)(h*sz.Width/sz.Height));}bmp=Document.Render(e.Index,w,h);thumbs.Add(e.Index,bmp);thumbOrder.Enqueue(e.Index);while(thumbs.Count>12){int oldest=thumbOrder.Dequeue();thumbs[oldest].Dispose();thumbs.Remove(oldest);}}int x=e.Bounds.X+(e.Bounds.Width-bmp.Width)/2,y=e.Bounds.Y+3;e.Graphics.DrawImageUnscaled(bmp,x,y);using(var p=new Pen((e.State&DrawItemState.Selected)!=0?Color.FromArgb(24,117,152):Color.FromArgb(210,216,222),(e.State&DrawItemState.Selected)!=0?2:1))e.Graphics.DrawRectangle(p,x-1,y-1,bmp.Width+1,bmp.Height+1);TextRenderer.DrawText(e.Graphics,(e.Index+1).ToString(),Font,new Rectangle(e.Bounds.X,e.Bounds.Bottom-24,e.Bounds.Width,20),e.ForeColor,TextFormatFlags.HorizontalCenter);}catch(Exception ex){Report(ex.Message);}}
        void PopulateOutline(){outline.BeginUpdate();outline.Nodes.Clear();if(Document!=null){foreach(var b in Document.Bookmarks())outline.Nodes.Add(BookmarkNode(b));if(outline.Nodes.Count==0)outline.Nodes.Add(new TreeNode("此文档没有目录"));}outline.EndUpdate();}
        static TreeNode BookmarkNode(Bookmark b){var n=new TreeNode(b.Title){Tag=b.Page};foreach(var c in b.Children)n.Nodes.Add(BookmarkNode(c));return n;}
        sealed class NoteItem {public int Index;public string Contents,Label;public override string ToString(){return Label;}}
