        internal ContextMenuStrip BuildContext(Point location){
            var c=new ContextMenuStrip{RenderMode=ToolStripRenderMode.System};
            if(fullScreen||readingMode)c.Items.Add(readingMode?"退出阅读模式（Esc）":slideShow?"退出幻灯片（Esc）":"退出全屏（Esc）",null,delegate{if(readingMode)ExitReadingMode();else ToggleFullScreen();});
            c.Items.Add("打开 PDF…",null,delegate{ChooseOpen();});
            c.Items.Add(split.Panel1Collapsed?"打开侧边栏（F12）":"隐藏侧边栏（F12）",null,delegate{ToggleSidebar();});
            if(Document==null){c.Items.Add("新建空白 PDF",null,delegate{NewDocument();});return c;}
            bool onPage=canvas.PageRectangle.Contains(location);Pick at=onPage?canvas.PickAt(location):null;N.Pt point=onPage?canvas.PointAt(location):new N.Pt();
            bool hasText=!String.IsNullOrEmpty(canvas.CopiedText());
            c.Items.Add(new ToolStripSeparator());
            c.Items.Add("复制所选文字",null,delegate{Copy();}).Enabled=hasText;
            if(!hasText&&at!=null&&at.Type==1&&!at.IsAnnotation)c.Items.Add("复制这里的文字",null,delegate{canvas.Selected=at;Copy();});
            c.Items.Add("复制当前页全部文字",null,delegate{try{string text=Document.SelectedText(0,N.FPDFText_CountChars(Document.TextPage));if(!String.IsNullOrEmpty(text))Clipboard.SetText(text);}catch(Exception e){Report(e.Message);}});
            c.Items.Add(new ToolStripSeparator());
            c.Items.Add(at!=null&&at.IsOcrText?"修改识别层文字…":at!=null&&at.IsAnnotation?"编辑便签…":"修改这里的文字…",null,delegate{canvas.Selected=at;EditSelected();}).Enabled=Document.CanEdit&&at!=null&&((!at.IsAnnotation&&at.Type==1)||(at.IsAnnotation&&at.Type==1));
            c.Items.Add("删除此对象",null,delegate{canvas.Selected=at;DeleteSelection();}).Enabled=Document.CanEdit&&at!=null;
            c.Items.Add("调整此对象大小…",null,delegate{canvas.Selected=at;ResizeSelection();}).Enabled=Document.CanEdit&&at!=null&&!at.IsAnnotation;
            c.Items.Add("在此添加文字…",null,delegate{InsertText(point);}).Enabled=Document.CanEdit&&onPage;
            c.Items.Add("在此添加便签…",null,delegate{InsertNote(point);}).Enabled=Document.CanEdit&&onPage;
            c.Items.Add(new ToolStripSeparator());
            c.Items.Add("适合页面",null,delegate{Fit(2);});c.Items.Add("适合宽度",null,delegate{Fit(1);});
            c.Items.Add("精确缩放比例…",null,delegate{string value=Dialogs.Ask(this,"缩放比例","输入 1%–6400% 的百分比，支持小数：",(canvas.Zoom*100).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+"%",false);if(value!=null)ApplyZoom(value);});
            var layouts=new ToolStripMenuItem("阅读布局");layouts.DropDownItems.Add("单页",null,delegate{SetLayout(PageLayout.Single);});layouts.DropDownItems.Add("双页",null,delegate{SetLayout(PageLayout.Double);});layouts.DropDownItems.Add("书籍",null,delegate{SetLayout(PageLayout.Book);});layouts.DropDownItems.Add("多页网格总览",null,delegate{SetLayout(PageLayout.Grid);});c.Items.Add(layouts);
            c.Items.Add("顺时针旋转",null,delegate{Run(delegate{Document.Rotate(1);});}).Enabled=Document.CanEdit;
            c.Items.Add("提取页面…",null,delegate{Extract();});c.Items.Add("导出当前页为图片…",null,delegate{ExportImage();});
            c.Items.Add(new ToolStripSeparator());c.Items.Add("打印…",null,delegate{Print();}).Enabled=Document.CanPrint;
            return c;
        }
        void ShowHelp(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"使用说明.txt");try{using(var f=new Form{Text="Mini PDF 使用说明",Font=Font,ClientSize=new Size(760,540),StartPosition=FormStartPosition.CenterParent}){var content=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Text=File.Exists(path)?File.ReadAllText(path):"Ctrl+O 打开，Ctrl+S 保存，Ctrl+F 查找。",Font=Font};f.Controls.Add(content);f.ShowDialog(this);}}catch(Exception e){Report(e.Message);}}
        void ShowLicenses(){string directory=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"许可证");using(var f=new Form{Text="开源许可（无需激活）",Font=Font,StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(760,500),AutoScaleDimensions=new SizeF(96,96),AutoScaleMode=AutoScaleMode.Dpi}){var list=new ListBox{Dock=DockStyle.Left,Width=205};var text=new TextBox{Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Both,WordWrap=false};f.Controls.Add(text);f.Controls.Add(list);if(Directory.Exists(directory))foreach(string path in Directory.GetFiles(directory))list.Items.Add(Path.GetFileName(path));list.SelectedIndexChanged+=delegate{if(list.SelectedItem!=null)text.Text=File.ReadAllText(Path.Combine(directory,list.SelectedItem.ToString()));};if(list.Items.Count>0)list.SelectedIndex=0;f.ShowDialog(this);}}
        protected override bool ProcessCmdKey(ref Message msg,Keys keys){if(keys==(Keys.Control|Keys.Tab)){NextTab(1);return true;}if(keys==(Keys.Control|Keys.Shift|Keys.Tab)){NextTab(-1);return true;}if(keys==(Keys.Control|Keys.F4)){CloseDocument();return true;}bool typing=zoomBox.ComboBox.ContainsFocus||query.TextBox.ContainsFocus||pageNumber.TextBox.ContainsFocus;if(typing&&keys==(Keys.Control|Keys.A)){if(zoomBox.ComboBox.ContainsFocus)zoomBox.ComboBox.SelectAll();else if(query.TextBox.ContainsFocus)query.SelectAll();else pageNumber.SelectAll();return true;}if(typing&&(keys==(Keys.Control|Keys.C)||keys==(Keys.Control|Keys.X)||keys==(Keys.Control|Keys.V)||keys==(Keys.Control|Keys.Z)||keys==(Keys.Control|Keys.Y)))return false;if(keys==Keys.F12||keys==Keys.F9){ToggleSidebar();return true;}if(keys==Keys.F11){ToggleFullScreen();return true;}if(keys==(Keys.Control|Keys.H)){ToggleReadingMode();return true;}if(keys==(Keys.Control|Keys.L)){SlideShow();return true;}if(keys==Keys.Escape){if(readingMode){ExitReadingMode();return true;}if(fullScreen){ToggleFullScreen();return true;}if(findbar.Visible){findbar.Visible=false;canvas.Focus();return true;}canvas.ClearSelection();SetTool(Tool.Read);return true;}if(canvas.ContainsFocus){if(keys==Keys.Enter){EditSelected();return true;}if(keys==Keys.Delete){DeleteSelection();return true;}if(keys==Keys.PageDown||keys==Keys.PageUp){TurnPage(keys==Keys.PageDown?1:-1);return true;}}if(keys==Keys.F10){if(readingMode)ExitReadingMode();if(fullScreen)ToggleFullScreen();toolbar.Visible=true;mainMenuButton.ShowDropDown();return true;}if(keys==(Keys.Control|Keys.D6)||keys==(Keys.Control|Keys.D7)||keys==(Keys.Control|Keys.D8)||keys==(Keys.Control|Keys.D9)){SetLayout((PageLayout)((int)(keys&Keys.KeyCode)-(int)Keys.D6));return true;}Action shortcut;if(shortcuts.TryGetValue(keys,out shortcut)){shortcut();return true;}return base.ProcessCmdKey(ref msg,keys);}
        protected override void Dispose(bool disposing){if(disposing){if(contextMenu!=null){contextMenu.Dispose();contextMenu=null;}ClearThumbnails();if(openTimer!=null){openTimer.Stop();openTimer.Dispose();openTimer=null;}foreach(var tab in documents)tab.Document.Dispose();documents.Clear();Document=null;activeTab=null;}base.Dispose(disposing);}
        internal void LoadForTest(PdfDocument doc){TrackDocument(doc);}
        internal PdfCanvas CanvasForTest {get{return canvas;}}
        internal void CloseContextForTest(){if(contextMenu!=null)contextMenu.Close();}
        internal void ToggleFullScreenForTest(){ToggleFullScreen();}
        internal void SlideShowForTest(){SlideShow();}
        internal bool SidebarShownForTest {get{return !split.Panel1Collapsed;}}
        internal bool SidebarButtonVisibleForTest {get{return sidebarHandle.Visible;}}
        internal void ClickSidebarHandleForTest(){sidebarHandle.PerformClick();}
        internal bool CompactForTest {get{return !menu.Visible&&!editbar.Visible&&!status.Visible&&toolbar.Visible&&toolbar.Height<=Math.Max(36,Font.Height*2+4);}}
        internal int DocumentTopForTest {get{return PointToClient(canvas.PointToScreen(Point.Empty)).Y;}}
        internal void OpenMainMenuForTest(){mainMenuButton.ShowDropDown();}
        internal void CloseMainMenuForTest(){mainMenuButton.HideDropDown();}
        internal bool ReadingModeForTest {get{return readingMode&&!fullScreen&&FormBorderStyle!=FormBorderStyle.None&&!menu.Visible&&!toolbar.Visible&&!editbar.Visible&&!findbar.Visible&&!status.Visible&&split.Panel1Collapsed&&!sidebarHandle.Visible;}}
    }
}
